-- Sacralink production schema (logical export via Supabase MCP). Structure only: no user data. Regenerated by scripts/split-mcp-backup.mjs.
-- Restore into a Supabase project or the local Supabase stack (it needs the auth schema and the anon/authenticated roles).

-- 0. extensions and enum types
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
DO $$ BEGIN CREATE TYPE public.user_role AS ENUM ('super_admin', 'admin', 'priest', 'volunteer', 'user', 'church_admin'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.appt_status AS ENUM ('pending', 'approved', 'rejected', 'rescheduled', 'completed', 'cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.sacrament_type AS ENUM ('baptism', 'wedding', 'funeral', 'confirmation', 'counseling', 'mass_intention', 'confession', 'anointing'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.donation_status AS ENUM ('pending', 'verified', 'rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- 1. tables, constraints, indexes, row level security
CREATE TABLE IF NOT EXISTS public.activity_logs (id uuid NOT NULL DEFAULT uuid_generate_v4(), user_id uuid, church_id uuid, action text NOT NULL, entity_type text, entity_id uuid, metadata jsonb, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()));
CREATE TABLE IF NOT EXISTS public.announcements (id uuid NOT NULL DEFAULT uuid_generate_v4(), church_id uuid NOT NULL, title text NOT NULL, body text NOT NULL, image_url text, is_pinned boolean DEFAULT false, is_active boolean DEFAULT true, expires_at timestamp with time zone, created_by uuid, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()));
CREATE TABLE IF NOT EXISTS public.appointment_changes (id uuid NOT NULL DEFAULT gen_random_uuid(), appointment_id uuid NOT NULL, church_id uuid NOT NULL, action text NOT NULL, reason text, before_values jsonb NOT NULL DEFAULT '{}'::jsonb, after_values jsonb NOT NULL DEFAULT '{}'::jsonb, changed_by uuid, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.appointment_documents (id uuid NOT NULL DEFAULT uuid_generate_v4(), appointment_id uuid NOT NULL, requirement_id uuid, file_url text NOT NULL, file_name text NOT NULL, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()), file_type text, file_size integer, uploaded_at timestamp with time zone DEFAULT now(), uploaded_by uuid);
CREATE TABLE IF NOT EXISTS public.appointments (id uuid NOT NULL DEFAULT uuid_generate_v4(), user_id uuid NOT NULL, church_id uuid NOT NULL, service_type text NOT NULL, appointment_date date NOT NULL, appointment_time time without time zone NOT NULL, status text NOT NULL DEFAULT 'pending'::text, notes text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), priest_id uuid, admin_feedback text, cancellation_reason text, rescheduled_from_date date, reschedule_reason text);
CREATE TABLE IF NOT EXISTS public.church_announcements (id uuid NOT NULL DEFAULT uuid_generate_v4(), church_id uuid NOT NULL, title character varying(255) NOT NULL, content text NOT NULL, created_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), is_pinned boolean DEFAULT false, category text NOT NULL DEFAULT 'general'::text, scheduled_at timestamp with time zone, target_audience text NOT NULL DEFAULT 'everyone'::text);
CREATE TABLE IF NOT EXISTS public.church_candle_prayers (id uuid NOT NULL DEFAULT gen_random_uuid(), church_id uuid NOT NULL, user_id uuid, intention_text text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.church_chat_logs (id uuid NOT NULL DEFAULT gen_random_uuid(), church_id uuid, user_id uuid, question text NOT NULL, answer text NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.church_favorites (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, church_id uuid NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.church_images (id uuid NOT NULL DEFAULT gen_random_uuid(), church_id uuid NOT NULL, image_url text NOT NULL, display_order integer DEFAULT 0, uploaded_by uuid, created_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.church_knowledge_chunks (id uuid NOT NULL DEFAULT gen_random_uuid(), church_id uuid NOT NULL, content text NOT NULL, embedding vector(768), source_type text NOT NULL, source_id uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.church_knowledge_files (id uuid NOT NULL DEFAULT gen_random_uuid(), church_id uuid NOT NULL, file_name text NOT NULL, file_path text NOT NULL, file_url text NOT NULL, uploaded_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.church_knowledge_sections (id uuid NOT NULL DEFAULT gen_random_uuid(), church_id uuid NOT NULL, title text NOT NULL, content text NOT NULL DEFAULT ''::text, display_order integer DEFAULT 0, created_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.churches (id uuid NOT NULL DEFAULT uuid_generate_v4(), name text NOT NULL, address text NOT NULL, description text, contact_number text, email text, latitude numeric, longitude numeric, livestream_url text, donation_qr_url text, panorama_url text, gcash_number text, maya_number text, operating_hours jsonb, is_active boolean DEFAULT true, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()), facebook_url text, status character varying(20) DEFAULT 'active'::character varying, gcash_qr_url text, maya_qr_url text, featured_image_url text, is_live boolean DEFAULT false, livestream_title text, livestream_platform text DEFAULT 'facebook'::text, candle_count integer DEFAULT 0, livestream_started_at timestamp with time zone, accept_cashless boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS public.conversation_participants (id uuid NOT NULL DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL, user_id uuid NOT NULL, last_read_at timestamp with time zone DEFAULT timezone('utc'::text, now()), created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()));
CREATE TABLE IF NOT EXISTS public.conversations (id uuid NOT NULL DEFAULT gen_random_uuid(), title text, type text NOT NULL DEFAULT 'direct'::text, church_id uuid, created_by uuid, created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()), category text DEFAULT 'general'::text, status text DEFAULT 'open'::text, ticket_number text);
CREATE TABLE IF NOT EXISTS public.donations (id uuid NOT NULL DEFAULT uuid_generate_v4(), user_id uuid NOT NULL, church_id uuid NOT NULL, amount numeric NOT NULL, reference_number text, proof_url text, status donation_status DEFAULT 'pending'::donation_status, verified_by uuid, verified_at timestamp with time zone, notes text, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()), show_as_supporter boolean NOT NULL DEFAULT false, purpose text, donor_notes text);
CREATE TABLE IF NOT EXISTS public.mass_schedules (id uuid NOT NULL DEFAULT uuid_generate_v4(), church_id uuid NOT NULL, day_of_week text NOT NULL, "time" time without time zone NOT NULL, language text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.messages (id uuid NOT NULL DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL, sender_id uuid NOT NULL, content text NOT NULL, message_type text NOT NULL DEFAULT 'text'::text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()));
CREATE TABLE IF NOT EXISTS public.notifications (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, type text NOT NULL, title text NOT NULL, message text NOT NULL, link text, is_read boolean DEFAULT false, created_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.parish_applications (id uuid NOT NULL DEFAULT gen_random_uuid(), applicant_id uuid, parish_name text NOT NULL, address text NOT NULL, contact_number text, email text, description text, latitude numeric, longitude numeric, gcash_number text, maya_number text, celebret_url text NOT NULL, decree_url text NOT NULL, status text NOT NULL DEFAULT 'pending'::text, checklist jsonb DEFAULT '{"notes": "", "rectory_call": false, "celebret_verified": false, "merchant_entity_verified": false}'::jsonb, reviewed_by uuid, reviewed_at timestamp with time zone, rejection_reason text, church_id uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.priest_availability (id uuid NOT NULL DEFAULT uuid_generate_v4(), priest_id uuid NOT NULL, church_id uuid, available_date date, start_time time without time zone, end_time time without time zone, is_blocked boolean DEFAULT false, notes text, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()), day_of_week integer, blackout_start date, blackout_end date, reason text NOT NULL DEFAULT 'Clergy Retreat / Leave'::text, updated_at timestamp with time zone DEFAULT now());
CREATE TABLE IF NOT EXISTS public.profiles (id uuid NOT NULL, email text, full_name text, role user_role DEFAULT 'user'::user_role, church_id uuid, avatar_url text, phone_number text, is_verified boolean DEFAULT false, fcm_token text, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()), updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()), assigned_church_id uuid, push_token text, is_priest boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS public.sacrament_requirements (id uuid NOT NULL DEFAULT uuid_generate_v4(), church_id uuid NOT NULL, service_type sacrament_type NOT NULL, requirement_name text NOT NULL, description text, is_required boolean DEFAULT true, created_at timestamp with time zone DEFAULT timezone('utc'::text, now()), allowed_file_types text[] DEFAULT ARRAY['pdf'::text, 'jpg'::text, 'jpeg'::text, 'png'::text], display_order integer DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.service_durations (id uuid NOT NULL DEFAULT uuid_generate_v4(), church_id uuid NOT NULL, service_type sacrament_type NOT NULL, duration_minutes integer NOT NULL DEFAULT 60, max_per_day integer DEFAULT 5);
CREATE TABLE IF NOT EXISTS public.system_announcements (id uuid NOT NULL DEFAULT uuid_generate_v4(), title character varying(255) NOT NULL, content text NOT NULL, type character varying(50) DEFAULT 'info'::character varying, created_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), expires_at timestamp with time zone, is_active boolean DEFAULT true);
ALTER TABLE activity_logs ADD CONSTRAINT activity_logs_pkey PRIMARY KEY (id);
ALTER TABLE announcements ADD CONSTRAINT announcements_pkey PRIMARY KEY (id);
ALTER TABLE appointment_changes ADD CONSTRAINT appointment_changes_pkey PRIMARY KEY (id);
ALTER TABLE appointment_changes ADD CONSTRAINT appointment_changes_action_check CHECK ((action = ANY (ARRAY['reschedule'::text, 'change_celebrant'::text, 'cancel'::text, 'mark_celebrated'::text, 'restore'::text, 'approve'::text, 'reject'::text])));
ALTER TABLE appointment_documents ADD CONSTRAINT appointment_documents_pkey PRIMARY KEY (id);
ALTER TABLE appointments ADD CONSTRAINT appointments_pkey PRIMARY KEY (id);
ALTER TABLE appointments ADD CONSTRAINT appointments_service_type_check CHECK ((service_type = ANY (ARRAY['Baptism'::text, 'Wedding'::text, 'Funeral'::text, 'Confirmation'::text, 'Blessing'::text, 'Other'::text])));
ALTER TABLE appointments ADD CONSTRAINT appointments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'rescheduled'::text, 'completed'::text, 'cancelled'::text])));
ALTER TABLE church_announcements ADD CONSTRAINT church_announcements_pkey PRIMARY KEY (id);
ALTER TABLE church_announcements ADD CONSTRAINT church_announcements_category_check CHECK ((category = ANY (ARRAY['general'::text, 'mass_schedule'::text, 'event'::text, 'emergency'::text, 'reminder'::text])));
ALTER TABLE church_announcements ADD CONSTRAINT church_announcements_content_not_empty CHECK ((length(TRIM(BOTH FROM content)) > 0));
ALTER TABLE church_announcements ADD CONSTRAINT church_announcements_target_audience_check CHECK ((target_audience = ANY (ARRAY['everyone'::text, 'parishioners'::text])));
ALTER TABLE church_announcements ADD CONSTRAINT church_announcements_title_not_empty CHECK ((length(TRIM(BOTH FROM title)) > 0));
ALTER TABLE church_candle_prayers ADD CONSTRAINT church_candle_prayers_pkey PRIMARY KEY (id);
ALTER TABLE church_chat_logs ADD CONSTRAINT church_chat_logs_pkey PRIMARY KEY (id);
ALTER TABLE church_favorites ADD CONSTRAINT church_favorites_pkey PRIMARY KEY (id);
ALTER TABLE church_favorites ADD CONSTRAINT church_favorites_user_id_church_id_key UNIQUE (user_id, church_id);
ALTER TABLE church_images ADD CONSTRAINT church_images_pkey PRIMARY KEY (id);
ALTER TABLE church_knowledge_chunks ADD CONSTRAINT church_knowledge_chunks_pkey PRIMARY KEY (id);
ALTER TABLE church_knowledge_files ADD CONSTRAINT church_knowledge_files_pkey PRIMARY KEY (id);
ALTER TABLE church_knowledge_sections ADD CONSTRAINT church_knowledge_sections_pkey PRIMARY KEY (id);
ALTER TABLE churches ADD CONSTRAINT churches_pkey PRIMARY KEY (id);
ALTER TABLE churches ADD CONSTRAINT churches_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'inactive'::character varying, 'unverified'::character varying, 'verified_active'::character varying])::text[])));
ALTER TABLE conversation_participants ADD CONSTRAINT conversation_participants_pkey PRIMARY KEY (id);
ALTER TABLE conversation_participants ADD CONSTRAINT conversation_participants_conversation_id_user_id_key UNIQUE (conversation_id, user_id);
ALTER TABLE conversations ADD CONSTRAINT conversations_pkey PRIMARY KEY (id);
ALTER TABLE donations ADD CONSTRAINT donations_pkey PRIMARY KEY (id);
ALTER TABLE donations ADD CONSTRAINT donations_amount_check CHECK ((amount > (0)::numeric));
ALTER TABLE mass_schedules ADD CONSTRAINT mass_schedules_pkey PRIMARY KEY (id);
ALTER TABLE messages ADD CONSTRAINT messages_pkey PRIMARY KEY (id);
ALTER TABLE notifications ADD CONSTRAINT notifications_pkey PRIMARY KEY (id);
ALTER TABLE parish_applications ADD CONSTRAINT parish_applications_pkey PRIMARY KEY (id);
ALTER TABLE parish_applications ADD CONSTRAINT parish_applications_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'under_review'::text, 'verified_active'::text, 'rejected'::text])));
ALTER TABLE priest_availability ADD CONSTRAINT priest_availability_pkey PRIMARY KEY (id);
ALTER TABLE priest_availability ADD CONSTRAINT priest_availability_day_of_week_check CHECK (((day_of_week >= 0) AND (day_of_week <= 6)));
ALTER TABLE profiles ADD CONSTRAINT profiles_pkey PRIMARY KEY (id);
ALTER TABLE profiles ADD CONSTRAINT profiles_email_key UNIQUE (email);
ALTER TABLE sacrament_requirements ADD CONSTRAINT sacrament_requirements_pkey PRIMARY KEY (id);
ALTER TABLE service_durations ADD CONSTRAINT service_durations_pkey PRIMARY KEY (id);
ALTER TABLE service_durations ADD CONSTRAINT service_durations_church_id_service_type_key UNIQUE (church_id, service_type);
ALTER TABLE system_announcements ADD CONSTRAINT system_announcements_pkey PRIMARY KEY (id);
ALTER TABLE system_announcements ADD CONSTRAINT system_announcements_content_not_empty CHECK ((length(TRIM(BOTH FROM content)) > 0));
ALTER TABLE system_announcements ADD CONSTRAINT system_announcements_title_not_empty CHECK ((length(TRIM(BOTH FROM title)) > 0));
ALTER TABLE system_announcements ADD CONSTRAINT system_announcements_type_check CHECK (((type)::text = ANY ((ARRAY['info'::character varying, 'warning'::character varying, 'maintenance'::character varying, 'success'::character varying])::text[])));
