-- 2. functions, triggers, views, storage buckets and realtime tables (comments are notes only)
CREATE OR REPLACE FUNCTION public.approve_appointment(p_appointment_id uuid, p_priest_id uuid DEFAULT NULL::uuid, p_admin_feedback text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_role TEXT;
  v_actor_church UUID;
  v_apt public.appointments%ROWTYPE;
  v_feedback TEXT := NULLIF(btrim(COALESCE(p_admin_feedback, '')), '');
  v_priest_ok BOOLEAN;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role::text, COALESCE(assigned_church_id, church_id)
    INTO v_actor_role, v_actor_church
  FROM public.profiles
  WHERE id = v_actor_id;

  SELECT * INTO v_apt
  FROM public.appointments
  WHERE id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Appointment not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor_role IS NULL
     OR v_actor_role NOT IN ('super_admin', 'admin', 'church_admin')
     OR (v_actor_role <> 'super_admin' AND v_actor_church IS DISTINCT FROM v_apt.church_id) THEN
    RAISE EXCEPTION 'Only the parish office can approve this appointment' USING ERRCODE = '42501';
  END IF;

  IF v_apt.status::text <> 'pending' THEN
    RAISE EXCEPTION 'Only pending appointments can be approved' USING ERRCODE = '22023';
  END IF;

  IF p_priest_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = p_priest_id
        AND (p.role::text IN ('priest', 'church_admin', 'admin') OR COALESCE(p.is_priest, false))
        AND (p.assigned_church_id = v_apt.church_id OR p.church_id = v_apt.church_id)
    ) INTO v_priest_ok;

    IF NOT v_priest_ok THEN
      RAISE EXCEPTION 'The selected celebrant is not a priest of this parish' USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.appointments
  SET status = 'approved',
      priest_id = p_priest_id,
      admin_feedback = v_feedback,
      updated_at = NOW()
  WHERE id = v_apt.id;

  INSERT INTO public.appointment_changes (
    appointment_id, church_id, action, reason, before_values, after_values, changed_by
  ) VALUES (
    v_apt.id,
    v_apt.church_id,
    'approve',
    v_feedback,
    jsonb_build_object('status', 'pending'),
    CASE WHEN p_priest_id IS NULL
         THEN jsonb_build_object('status', 'approved')
         ELSE jsonb_build_object('status', 'approved', 'priest_id', p_priest_id) END,
    v_actor_id
  );

  INSERT INTO public.notifications (user_id, type, title, message, link)
  VALUES (
    v_apt.user_id,
    'appointment_approved',
    'Appointment Approved',
    'Your ' || v_apt.service_type || ' appointment has been approved!',
    '/appointments'
  );

  IF p_priest_id IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, type, title, message, link)
    VALUES (
      p_priest_id,
      'appointment',
      'New Sacramental Assignment',
      'You have been assigned as celebrant for a ' || v_apt.service_type
        || ' on ' || v_apt.appointment_date::text
        || ' at ' || to_char(v_apt.appointment_time::time, 'FMHH12:MI AM') || '.',
      '/appointments'
    );
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cancel_appointment(p_appointment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_role TEXT;
  v_actor_church UUID;
  v_apt public.appointments%ROWTYPE;
  v_reason TEXT := btrim(COALESCE(p_reason, ''));
  v_when TEXT;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_reason = '' THEN
    RAISE EXCEPTION 'A reason is required to cancel an appointment' USING ERRCODE = '22023';
  END IF;

  SELECT role::text, COALESCE(assigned_church_id, church_id)
    INTO v_actor_role, v_actor_church
  FROM public.profiles
  WHERE id = v_actor_id;

  SELECT * INTO v_apt
  FROM public.appointments
  WHERE id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Appointment not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor_role IS NULL
     OR v_actor_role NOT IN ('super_admin', 'admin', 'church_admin')
     OR (v_actor_role <> 'super_admin' AND v_actor_church IS DISTINCT FROM v_apt.church_id) THEN
    RAISE EXCEPTION 'Only the parish office can cancel this appointment' USING ERRCODE = '42501';
  END IF;

  IF v_apt.status::text <> 'approved' THEN
    RAISE EXCEPTION 'Only approved appointments can be cancelled' USING ERRCODE = '22023';
  END IF;

  UPDATE public.appointments
  SET status = 'cancelled',
      cancellation_reason = v_reason,
      updated_at = NOW()
  WHERE id = v_apt.id;

  INSERT INTO public.appointment_changes (
    appointment_id, church_id, action, reason, before_values, after_values, changed_by
  ) VALUES (
    v_apt.id,
    v_apt.church_id,
    'cancel',
    v_reason,
    jsonb_build_object('status', v_apt.status::text),
    jsonb_build_object('status', 'cancelled'),
    v_actor_id
  );

  v_when := to_char(v_apt.appointment_date::date, 'FMMon DD, YYYY')
            || ' at ' || to_char(v_apt.appointment_time::time, 'FMHH12:MI AM');

  INSERT INTO public.notifications (user_id, type, title, message, link)
  VALUES (
    v_apt.user_id,
    'appointment_cancelled',
    'Appointment Cancelled',
    'Your ' || v_apt.service_type || ' on ' || v_when || ' has been cancelled. Reason: ' || v_reason,
    '/appointments'
  );

  IF v_apt.priest_id IS NOT NULL AND v_apt.priest_id IS DISTINCT FROM v_apt.user_id THEN
    INSERT INTO public.notifications (user_id, type, title, message, link)
    VALUES (
      v_apt.priest_id,
      'appointment_cancelled',
      'Appointment Cancelled',
      'The ' || v_apt.service_type || ' on ' || v_when || ' that you were to preside at has been cancelled. Reason: ' || v_reason,
      '/appointments'
    );
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.change_appointment_celebrant(p_appointment_id uuid, p_new_priest_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_role TEXT;
  v_actor_church UUID;
  v_apt public.appointments%ROWTYPE;
  v_reason TEXT := btrim(COALESCE(p_reason, ''));
  v_new_is_celebrant BOOLEAN;
  v_old_priest_id UUID;
  v_when TEXT;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_reason = '' THEN
    RAISE EXCEPTION 'A reason is required to change the celebrant' USING ERRCODE = '22023';
  END IF;

  IF p_new_priest_id IS NULL THEN
    RAISE EXCEPTION 'A new celebrant is required' USING ERRCODE = '22023';
  END IF;

  SELECT role::text, COALESCE(assigned_church_id, church_id)
    INTO v_actor_role, v_actor_church
  FROM public.profiles
  WHERE id = v_actor_id;

  SELECT * INTO v_apt
  FROM public.appointments
  WHERE id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Appointment not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor_role IS NULL
     OR v_actor_role NOT IN ('super_admin', 'admin', 'church_admin')
     OR (v_actor_role <> 'super_admin' AND v_actor_church IS DISTINCT FROM v_apt.church_id) THEN
    RAISE EXCEPTION 'Only the parish office can change the celebrant' USING ERRCODE = '42501';
  END IF;

  IF v_apt.status::text <> 'approved' THEN
    RAISE EXCEPTION 'Only approved appointments can have their celebrant changed' USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = p_new_priest_id
      AND (p.role::text IN ('priest', 'church_admin', 'admin') OR COALESCE(p.is_priest, false))
      AND (p.assigned_church_id = v_apt.church_id OR p.church_id = v_apt.church_id)
  ) INTO v_new_is_celebrant;

  IF NOT v_new_is_celebrant THEN
    RAISE EXCEPTION 'The selected celebrant is not a priest of this parish' USING ERRCODE = '22023';
  END IF;

  v_old_priest_id := v_apt.priest_id;

  UPDATE public.appointments
  SET priest_id = p_new_priest_id,
      updated_at = NOW()
  WHERE id = v_apt.id;

  INSERT INTO public.appointment_changes (
    appointment_id, church_id, action, reason, before_values, after_values, changed_by
  ) VALUES (
    v_apt.id,
    v_apt.church_id,
    'change_celebrant',
    v_reason,
    jsonb_build_object('priest_id', v_old_priest_id),
    jsonb_build_object('priest_id', p_new_priest_id),
    v_actor_id
  );

  v_when := to_char(v_apt.appointment_date::date, 'FMMon DD, YYYY')
            || ' at ' || to_char(v_apt.appointment_time::time, 'FMHH12:MI AM');

  IF p_new_priest_id IS DISTINCT FROM v_old_priest_id THEN
    INSERT INTO public.notifications (user_id, type, title, message, link)
    VALUES (
      p_new_priest_id,
      'appointment',
      'New Sacramental Assignment',
      'You have been assigned as celebrant for a ' || v_apt.service_type || ' on ' || v_when || '.',
      '/appointments'
    );

    IF v_old_priest_id IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, type, title, message, link)
      VALUES (
        v_old_priest_id,
        'appointment',
        'Celebrant Assignment Removed',
        'You are no longer the celebrant for the ' || v_apt.service_type || ' on ' || v_when || '. Reason: ' || v_reason,
        '/appointments'
      );
    END IF;
  END IF;
END;
$function$
;

