CREATE OR REPLACE FUNCTION public.light_church_candle(target_church_id uuid, user_intention text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    new_count INTEGER;
BEGIN
    UPDATE public.churches
    SET candle_count = COALESCE(candle_count, 0) + 1
    WHERE id = target_church_id
    RETURNING candle_count INTO new_count;

    INSERT INTO public.church_candle_prayers (church_id, user_id, intention_text)
    VALUES (target_church_id, auth.uid(), user_intention);

    RETURN COALESCE(new_count, 1);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_appointment_celebrated(p_appointment_id uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_role TEXT;
  v_actor_church UUID;
  v_apt public.appointments%ROWTYPE;
  v_note TEXT := NULLIF(btrim(COALESCE(p_note, '')), '');
  v_is_office BOOLEAN;
  v_is_celebrant BOOLEAN;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role::text, COALESCE(assigned_church_id, church_id)
    INTO v_actor_role, v_actor_church
  FROM public.profiles
  WHERE id = v_actor_id;

  SELECT * INTO v_apt
  FROM public.appointments
  WHERE id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Appointment not found' USING ERRCODE = 'P0002';
  END IF;

  v_is_office := v_actor_role IN ('super_admin', 'admin', 'church_admin')
                 AND (v_actor_role = 'super_admin' OR v_actor_church IS NOT DISTINCT FROM v_apt.church_id);
  v_is_celebrant := v_apt.priest_id IS NOT NULL AND v_apt.priest_id = v_actor_id;

  IF NOT (COALESCE(v_is_office, false) OR v_is_celebrant) THEN
    RAISE EXCEPTION 'Only the parish office or the celebrant of this appointment can mark it celebrated'
      USING ERRCODE = '42501';
  END IF;

  IF v_apt.status::text <> 'approved' THEN
    RAISE EXCEPTION 'Only approved appointments can be marked celebrated' USING ERRCODE = '22023';
  END IF;

  IF NOT COALESCE(v_is_office, false)
     AND (v_apt.appointment_date::date + v_apt.appointment_time::time)
         > ((NOW() AT TIME ZONE 'UTC') + INTERVAL '14 hours') THEN
    RAISE EXCEPTION 'This appointment has not started yet' USING ERRCODE = '22023';
  END IF;

  UPDATE public.appointments
  SET status = 'completed',
      updated_at = NOW()
  WHERE id = v_apt.id;

  INSERT INTO public.appointment_changes (
    appointment_id, church_id, action, reason, before_values, after_values, changed_by
  ) VALUES (
    v_apt.id,
    v_apt.church_id,
    'mark_celebrated',
    v_note,
    jsonb_build_object('status', v_apt.status::text),
    jsonb_build_object('status', 'completed'),
    v_actor_id
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.match_church_knowledge(query_embedding vector, match_church_id uuid, match_count integer DEFAULT 5)
 RETURNS TABLE(id uuid, content text, source_type text, similarity double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    RETURN QUERY
    SELECT
        ckc.id,
        ckc.content,
        ckc.source_type,
        1 - (ckc.embedding <=> query_embedding) AS similarity
    FROM church_knowledge_chunks ckc
    WHERE ckc.church_id = match_church_id
      AND ckc.embedding IS NOT NULL
    ORDER BY ckc.embedding <=> query_embedding
    LIMIT match_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_church_stats()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.church_stats;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reject_appointment(p_appointment_id uuid, p_admin_feedback text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_role TEXT;
  v_actor_church UUID;
  v_apt public.appointments%ROWTYPE;
  v_feedback TEXT := NULLIF(btrim(COALESCE(p_admin_feedback, '')), '');
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role::text, COALESCE(assigned_church_id, church_id)
    INTO v_actor_role, v_actor_church
  FROM public.profiles
  WHERE id = v_actor_id;

  SELECT * INTO v_apt
  FROM public.appointments
  WHERE id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Appointment not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor_role IS NULL
     OR v_actor_role NOT IN ('super_admin', 'admin', 'church_admin')
     OR (v_actor_role <> 'super_admin' AND v_actor_church IS DISTINCT FROM v_apt.church_id) THEN
    RAISE EXCEPTION 'Only the parish office can reject this appointment' USING ERRCODE = '42501';
  END IF;

  IF v_apt.status::text <> 'pending' THEN
    RAISE EXCEPTION 'Only pending appointments can be rejected' USING ERRCODE = '22023';
  END IF;

  UPDATE public.appointments
  SET status = 'rejected',
      admin_feedback = COALESCE(v_feedback, admin_feedback),
      updated_at = NOW()
  WHERE id = v_apt.id;

  INSERT INTO public.appointment_changes (
    appointment_id, church_id, action, reason, before_values, after_values, changed_by
  ) VALUES (
    v_apt.id,
    v_apt.church_id,
    'reject',
    v_feedback,
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'rejected'),
    v_actor_id
  );

  INSERT INTO public.notifications (user_id, type, title, message, link)
  VALUES (
    v_apt.user_id,
    'appointment_rejected',
    'Appointment Rejected',
    'Your ' || v_apt.service_type || ' appointment has been rejected.',
    '/appointments'
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reschedule_appointment(p_appointment_id uuid, p_new_date date, p_new_time time without time zone, p_reason text, p_new_priest_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_role TEXT;
  v_actor_church UUID;
  v_apt public.appointments%ROWTYPE;
  v_reason TEXT := btrim(COALESCE(p_reason, ''));
  v_old_priest_id UUID;
  v_final_priest_id UUID;
  v_priest_changed BOOLEAN;
  v_is_celebrant BOOLEAN;
  v_old_when TEXT;
  v_new_when TEXT;
  v_before JSONB;
  v_after JSONB;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_reason = '' THEN
    RAISE EXCEPTION 'A reason is required to reschedule an appointment' USING ERRCODE = '22023';
  END IF;

  IF p_new_date IS NULL OR p_new_time IS NULL THEN
    RAISE EXCEPTION 'A new date and time are required' USING ERRCODE = '22023';
  END IF;

  IF p_new_date < (NOW() AT TIME ZONE 'UTC')::date THEN
    RAISE EXCEPTION 'An appointment cannot be rescheduled to a date in the past' USING ERRCODE = '22023';
  END IF;

  SELECT role::text, COALESCE(assigned_church_id, church_id)
    INTO v_actor_role, v_actor_church
  FROM public.profiles
  WHERE id = v_actor_id;

  SELECT * INTO v_apt
  FROM public.appointments
  WHERE id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Appointment not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor_role IS NULL
     OR v_actor_role NOT IN ('super_admin', 'admin', 'church_admin')
     OR (v_actor_role <> 'super_admin' AND v_actor_church IS DISTINCT FROM v_apt.church_id) THEN
    RAISE EXCEPTION 'Only the parish office can reschedule this appointment' USING ERRCODE = '42501';
  END IF;

  IF v_apt.status::text <> 'approved' THEN
    RAISE EXCEPTION 'Only approved appointments can be rescheduled' USING ERRCODE = '22023';
  END IF;

  v_old_priest_id := v_apt.priest_id;
  v_priest_changed := p_new_priest_id IS NOT NULL AND p_new_priest_id IS DISTINCT FROM v_old_priest_id;
  v_final_priest_id := CASE WHEN v_priest_changed THEN p_new_priest_id ELSE v_old_priest_id END;

  IF p_new_date = v_apt.appointment_date::date
     AND p_new_time = v_apt.appointment_time::time
     AND NOT v_priest_changed THEN
    RAISE EXCEPTION 'Choose a different date, time or celebrant to reschedule' USING ERRCODE = '22023';
  END IF;

  IF v_priest_changed THEN
    SELECT EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = p_new_priest_id
        AND (p.role::text IN ('priest', 'church_admin', 'admin') OR COALESCE(p.is_priest, false))
        AND (p.assigned_church_id = v_apt.church_id OR p.church_id = v_apt.church_id)
    ) INTO v_is_celebrant;

    IF NOT v_is_celebrant THEN
      RAISE EXCEPTION 'The selected celebrant is not a priest of this parish' USING ERRCODE = '22023';
    END IF;
  END IF;

  v_before := jsonb_build_object(
    'appointment_date', v_apt.appointment_date::date,
    'appointment_time', v_apt.appointment_time::time
  );
  v_after := jsonb_build_object(
    'appointment_date', p_new_date,
    'appointment_time', p_new_time
  );
  IF v_priest_changed THEN
    v_before := v_before || jsonb_build_object('priest_id', v_old_priest_id);
    v_after := v_after || jsonb_build_object('priest_id', p_new_priest_id);
  END IF;

  UPDATE public.appointments
  SET appointment_date = p_new_date,
      appointment_time = p_new_time,
      priest_id = v_final_priest_id,
      rescheduled_from_date = v_apt.appointment_date::date,
      reschedule_reason = v_reason,
      updated_at = NOW()
  WHERE id = v_apt.id;

  INSERT INTO public.appointment_changes (
    appointment_id, church_id, action, reason, before_values, after_values, changed_by
  ) VALUES (
    v_apt.id, v_apt.church_id, 'reschedule', v_reason, v_before, v_after, v_actor_id
  );

  v_old_when := to_char(v_apt.appointment_date::date, 'FMMon DD, YYYY')
                || ' at ' || to_char(v_apt.appointment_time::time, 'FMHH12:MI AM');
  v_new_when := to_char(p_new_date, 'FMMon DD, YYYY')
                || ' at ' || to_char(p_new_time, 'FMHH12:MI AM');

  INSERT INTO public.notifications (user_id, type, title, message, link)
  VALUES (
    v_apt.user_id,
    'appointment_rescheduled',
    'Appointment Rescheduled',
    'Your ' || v_apt.service_type || ' on ' || v_old_when || ' has been rescheduled to ' || v_new_when
      || '. Reason: ' || v_reason,
    '/appointments'
  );

  IF v_final_priest_id IS NOT NULL AND v_final_priest_id IS DISTINCT FROM v_apt.user_id THEN
    IF v_priest_changed THEN
      INSERT INTO public.notifications (user_id, type, title, message, link)
      VALUES (
        v_final_priest_id,
        'appointment',
        'New Sacramental Assignment',
        'You have been assigned as celebrant for a ' || v_apt.service_type || ' on ' || v_new_when
          || ' (rescheduled from ' || v_old_when || '). Reason: ' || v_reason,
        '/appointments'
      );
    ELSE
      INSERT INTO public.notifications (user_id, type, title, message, link)
      VALUES (
        v_final_priest_id,
        'appointment_rescheduled',
        'Appointment Rescheduled',
        'The ' || v_apt.service_type || ' on ' || v_old_when || ' that you are to preside at has been rescheduled to '
          || v_new_when || '. Reason: ' || v_reason,
        '/appointments'
      );
    END IF;
  END IF;

  IF v_priest_changed
     AND v_old_priest_id IS NOT NULL
     AND v_old_priest_id IS DISTINCT FROM v_apt.user_id THEN
    INSERT INTO public.notifications (user_id, type, title, message, link)
    VALUES (
      v_old_priest_id,
      'appointment',
      'Celebrant Assignment Removed',
      'The ' || v_apt.service_type || ' on ' || v_old_when || ' was rescheduled to ' || v_new_when
        || ' and you are no longer the celebrant. Reason: ' || v_reason,
      '/appointments'
    );
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.restore_appointment(p_appointment_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor_role TEXT;
  v_actor_church UUID;
  v_apt public.appointments%ROWTYPE;
  v_reason TEXT := btrim(COALESCE(p_reason, ''));
  v_old_status TEXT;
  v_when TEXT;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF v_reason = '' THEN
    RAISE EXCEPTION 'A reason is required to restore an appointment' USING ERRCODE = '22023';
  END IF;

  SELECT role::text, COALESCE(assigned_church_id, church_id)
    INTO v_actor_role, v_actor_church
  FROM public.profiles
  WHERE id = v_actor_id;

  SELECT * INTO v_apt
  FROM public.appointments
  WHERE id = p_appointment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Appointment not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_actor_role IS NULL
     OR v_actor_role NOT IN ('super_admin', 'admin', 'church_admin')
     OR (v_actor_role <> 'super_admin' AND v_actor_church IS DISTINCT FROM v_apt.church_id) THEN
    RAISE EXCEPTION 'Only the parish office can restore this appointment' USING ERRCODE = '42501';
  END IF;

  v_old_status := v_apt.status::text;

  IF v_old_status NOT IN ('cancelled', 'completed') THEN
    RAISE EXCEPTION 'Only cancelled or celebrated appointments can be restored' USING ERRCODE = '22023';
  END IF;

  UPDATE public.appointments
  SET status = 'approved',
      cancellation_reason = CASE WHEN v_old_status = 'cancelled' THEN NULL ELSE cancellation_reason END,
      updated_at = NOW()
  WHERE id = v_apt.id;

  INSERT INTO public.appointment_changes (
    appointment_id, church_id, action, reason, before_values, after_values, changed_by
  ) VALUES (
    v_apt.id,
    v_apt.church_id,
    'restore',
    v_reason,
    jsonb_build_object('status', v_old_status),
    jsonb_build_object('status', 'approved'),
    v_actor_id
  );

  IF v_old_status = 'cancelled' THEN
    v_when := to_char(v_apt.appointment_date::date, 'FMMon DD, YYYY')
              || ' at ' || to_char(v_apt.appointment_time::time, 'FMHH12:MI AM');

    INSERT INTO public.notifications (user_id, type, title, message, link)
    VALUES (
      v_apt.user_id,
      'appointment',
      'Appointment Restored',
      'Your ' || v_apt.service_type || ' on ' || v_when || ' has been restored and is approved again. Reason: ' || v_reason,
      '/appointments'
    );

    IF v_apt.priest_id IS NOT NULL AND v_apt.priest_id IS DISTINCT FROM v_apt.user_id THEN
      INSERT INTO public.notifications (user_id, type, title, message, link)
      VALUES (
        v_apt.priest_id,
        'appointment',
        'Appointment Restored',
        'The ' || v_apt.service_type || ' on ' || v_when || ' that you are to preside at has been restored. Reason: ' || v_reason,
        '/appointments'
      );
    END IF;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.transfer_super_admin(target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    caller_id UUID;
    caller_role TEXT;
    target_exists BOOLEAN;
BEGIN
    caller_id := auth.uid();
    IF caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: No active session');
    END IF;

    -- Verify caller is super_admin
    SELECT role INTO caller_role FROM public.profiles WHERE id = caller_id;
    IF caller_role IS NULL OR caller_role != 'super_admin' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Forbidden: Only the current Super Admin can transfer ownership');
    END IF;

    IF caller_id = target_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Target user is already the Super Admin');
    END IF;

    -- Check target user exists
    SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id = target_user_id) INTO target_exists;
    IF NOT target_exists THEN
        RETURN jsonb_build_object('success', false, 'error', 'Target user not found');
    END IF;

    -- Atomic transfer:
    -- 1. Demote current super admin to admin
    UPDATE public.profiles
    SET role = 'admin', updated_at = NOW()
    WHERE id = caller_id;

    -- 2. Promote target user to super_admin (clearing church assignments as super_admin oversees all)
    UPDATE public.profiles
    SET role = 'super_admin', assigned_church_id = NULL, church_id = NULL, updated_at = NOW()
    WHERE id = target_user_id;

    -- 3. Log to activity_logs
    INSERT INTO public.activity_logs (user_id, action, entity_type, entity_id, metadata)
    VALUES (
        caller_id,
        'transfer_super_admin',
        'profiles',
        target_user_id,
        jsonb_build_object('previous_owner_id', caller_id, 'new_owner_id', target_user_id)
    );

    RETURN jsonb_build_object('success', true);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_church_announcements_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_church_livestream(p_church_id uuid, p_is_live boolean, p_livestream_url text DEFAULT NULL::text, p_livestream_title text DEFAULT NULL::text, p_livestream_platform text DEFAULT 'youtube'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID;
    v_user_role user_role;
    v_assigned_church UUID;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT role, COALESCE(assigned_church_id, church_id)
    INTO v_user_role, v_assigned_church
    FROM profiles
    WHERE id = v_user_id;

    IF v_user_role NOT IN ('super_admin', 'admin') AND (v_assigned_church IS NULL OR v_assigned_church <> p_church_id) THEN
        RAISE EXCEPTION 'Permission denied to manage this church livestream';
    END IF;

    UPDATE churches
    SET 
        is_live = p_is_live,
        livestream_url = COALESCE(p_livestream_url, livestream_url),
        livestream_title = COALESCE(p_livestream_title, livestream_title),
        livestream_platform = COALESCE(p_livestream_platform, livestream_platform, 'youtube'),
        livestream_started_at = CASE WHEN p_is_live THEN NOW() ELSE livestream_started_at END,
        updated_at = NOW()
    WHERE id = p_church_id;

    RETURN jsonb_build_object('success', true, 'is_live', p_is_live);
END;
$function$
;

