CREATE TRIGGER announcements_updated_at BEFORE UPDATE ON public.announcements FOR EACH ROW EXECUTE FUNCTION handle_updated_at();

CREATE TRIGGER update_church_announcements_timestamp BEFORE UPDATE ON public.church_announcements FOR EACH ROW EXECUTE FUNCTION update_church_announcements_updated_at();

CREATE TRIGGER churches_updated_at BEFORE UPDATE ON public.churches FOR EACH ROW EXECUTE FUNCTION handle_updated_at();

CREATE TRIGGER tr_update_conversation_timestamp AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION handle_new_message_conversation_timestamp();

CREATE TRIGGER trg_priest_availability_updated_at BEFORE UPDATE ON public.priest_availability FOR EACH ROW EXECUTE FUNCTION update_priest_availability_updated_at();

CREATE TRIGGER profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION handle_updated_at();

CREATE TRIGGER update_system_announcements_timestamp BEFORE UPDATE ON public.system_announcements FOR EACH ROW EXECUTE FUNCTION update_system_announcements_updated_at();

CREATE MATERIALIZED VIEW IF NOT EXISTS public.church_stats AS  SELECT c.id AS church_id,
    c.name AS church_name,
    c.status AS church_status,
    count(DISTINCT a.id) AS total_appointments,
    count(DISTINCT a.id) FILTER (WHERE (a.status = 'pending'::text)) AS pending_appointments,
    count(DISTINCT a.id) FILTER (WHERE (a.status = 'approved'::text)) AS approved_appointments,
    count(DISTINCT a.id) FILTER (WHERE ((a.status = 'approved'::text) AND (a.appointment_date >= CURRENT_DATE))) AS upcoming_appointments,
    count(DISTINCT a.id) FILTER (WHERE (a.status = 'completed'::text)) AS completed_appointments,
    count(DISTINCT p.id) FILTER (WHERE ((p.assigned_church_id = c.id) AND (p.role = ANY (ARRAY['church_admin'::user_role, 'volunteer'::user_role])))) AS staff_count,
    count(DISTINCT a.id) FILTER (WHERE (a.created_at >= (now() - '30 days'::interval))) AS appointments_last_30_days,
    now() AS last_updated
   FROM ((churches c
     LEFT JOIN appointments a ON ((a.church_id = c.id)))
     LEFT JOIN profiles p ON (true))
  GROUP BY c.id, c.name, c.status;

-- storage bucket: id='appointment-documents' name='appointment-documents' public=t file_size_limit=null

-- storage bucket: id='avatars' name='avatars' public=t file_size_limit=524288

-- storage bucket: id='church-images' name='church-images' public=t file_size_limit=null

-- storage bucket: id='church-knowledge-files' name='church-knowledge-files' public=t file_size_limit=1048576

-- storage bucket: id='donation-proofs' name='donation-proofs' public=f file_size_limit=10485760

-- realtime publication supabase_realtime includes public.appointments

-- realtime publication supabase_realtime includes public.churches

-- realtime publication supabase_realtime includes public.conversation_participants

-- realtime publication supabase_realtime includes public.conversations

-- realtime publication supabase_realtime includes public.donations

-- realtime publication supabase_realtime includes public.messages

-- realtime publication supabase_realtime includes public.notifications
CREATE UNIQUE INDEX idx_church_stats_church_id ON public.church_stats USING btree (church_id);
CREATE INDEX idx_church_stats_status ON public.church_stats USING btree (church_status);

-- 3. row level security policies
CREATE POLICY "Admins can view church activity logs" ON public.activity_logs AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::user_role, 'super_admin'::user_role])) AND ((profiles.church_id = activity_logs.church_id) OR (profiles.role = 'super_admin'::user_role))))));
CREATE POLICY "System can insert activity logs" ON public.activity_logs AS PERMISSIVE FOR INSERT TO public WITH CHECK (true);
CREATE POLICY "Admins can manage church announcements" ON public.announcements AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::user_role, 'volunteer'::user_role, 'super_admin'::user_role])) AND ((profiles.church_id = announcements.church_id) OR (profiles.role = 'super_admin'::user_role))))));
CREATE POLICY "Anyone can view active announcements" ON public.announcements AS PERMISSIVE FOR SELECT TO public USING ((is_active = true));
CREATE POLICY "Office and celebrant can view appointment changes" ON public.appointment_changes AS PERMISSIVE FOR SELECT TO authenticated USING (((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role = 'super_admin'::user_role) OR ((profiles.role = ANY (ARRAY['admin'::user_role, 'church_admin'::user_role])) AND (COALESCE(profiles.assigned_church_id, profiles.church_id) = appointment_changes.church_id)))))) OR (EXISTS ( SELECT 1
   FROM appointments
  WHERE ((appointments.id = appointment_changes.appointment_id) AND (appointments.priest_id = auth.uid()))))));
CREATE POLICY "Admins can view all documents" ON public.appointment_documents AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::user_role, 'super_admin'::user_role, 'church_admin'::user_role]))))));
CREATE POLICY "Users can delete own documents" ON public.appointment_documents AS PERMISSIVE FOR DELETE TO authenticated USING ((uploaded_by = auth.uid()));
CREATE POLICY "Users can upload documents for own appointments" ON public.appointment_documents AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((uploaded_by = auth.uid()));
CREATE POLICY "Users can view own documents" ON public.appointment_documents AS PERMISSIVE FOR SELECT TO authenticated USING ((uploaded_by = auth.uid()));
CREATE POLICY "Church staff can update church appointments" ON public.appointments AS PERMISSIVE FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role = 'super_admin'::user_role) OR (((profiles.role = 'church_admin'::user_role) OR (profiles.role = 'volunteer'::user_role)) AND (profiles.assigned_church_id = appointments.church_id)) OR ((profiles.role = 'admin'::user_role) AND (profiles.church_id = appointments.church_id)))))));
CREATE POLICY "Church staff can view church appointments" ON public.appointments AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role = 'super_admin'::user_role) OR (((profiles.role = 'church_admin'::user_role) OR (profiles.role = 'volunteer'::user_role)) AND (profiles.assigned_church_id = appointments.church_id)) OR ((profiles.role = 'admin'::user_role) AND (profiles.church_id = appointments.church_id)))))));
CREATE POLICY "Priests can update their assigned appointments" ON public.appointments AS PERMISSIVE FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'priest'::user_role) AND ((appointments.priest_id = auth.uid()) OR (profiles.church_id = appointments.church_id) OR (profiles.assigned_church_id = appointments.church_id))))));
CREATE POLICY "Priests can view their appointments" ON public.appointments AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'priest'::user_role) AND ((appointments.priest_id = auth.uid()) OR (profiles.church_id = appointments.church_id) OR (profiles.assigned_church_id = appointments.church_id))))));
CREATE POLICY "Users can cancel pending appointments" ON public.appointments AS PERMISSIVE FOR DELETE TO public USING (((auth.uid() = user_id) AND (status = 'pending'::text)));
CREATE POLICY "Users can create appointments" ON public.appointments AS PERMISSIVE FOR INSERT TO public WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can view their own appointments" ON public.appointments AS PERMISSIVE FOR SELECT TO public USING ((auth.uid() = user_id));
CREATE POLICY "Church staff can manage their church announcements" ON public.church_announcements AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role = 'super_admin'::user_role) OR (profiles.role = 'admin'::user_role) OR (((profiles.role = 'church_admin'::user_role) OR (profiles.role = 'volunteer'::user_role) OR (profiles.role = 'priest'::user_role)) AND (COALESCE(profiles.assigned_church_id, profiles.church_id) = church_announcements.church_id))))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role = 'super_admin'::user_role) OR (profiles.role = 'admin'::user_role) OR (((profiles.role = 'church_admin'::user_role) OR (profiles.role = 'volunteer'::user_role) OR (profiles.role = 'priest'::user_role)) AND (COALESCE(profiles.assigned_church_id, profiles.church_id) = church_announcements.church_id)))))));
CREATE POLICY "Public can read church announcements" ON public.church_announcements AS PERMISSIVE FOR SELECT TO public USING ((church_id IN ( SELECT churches.id
   FROM churches
  WHERE ((churches.status)::text = ANY ((ARRAY['active'::character varying, 'verified_active'::character varying])::text[])))));
CREATE POLICY "Anyone can view candle prayers" ON public.church_candle_prayers AS PERMISSIVE FOR SELECT TO public USING (true);
CREATE POLICY "Anyone or authenticated can insert candle prayers" ON public.church_candle_prayers AS PERMISSIVE FOR INSERT TO public WITH CHECK (true);
CREATE POLICY "Admins can read all chat logs" ON public.church_chat_logs AS PERMISSIVE FOR SELECT TO authenticated USING ((get_current_user_role() = ANY (ARRAY['admin'::text, 'super_admin'::text, 'church_admin'::text])));
CREATE POLICY "Anyone authenticated can insert chat logs" ON public.church_chat_logs AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "Users can read their own chat logs" ON public.church_chat_logs AS PERMISSIVE FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Admins can read all favorites" ON public.church_favorites AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::user_role, 'admin'::user_role, 'church_admin'::user_role]))))));
CREATE POLICY "Users can follow a church" ON public.church_favorites AS PERMISSIVE FOR INSERT TO public WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can unfollow a church" ON public.church_favorites AS PERMISSIVE FOR DELETE TO public USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own favorites" ON public.church_favorites AS PERMISSIVE FOR SELECT TO public USING ((auth.uid() = user_id));
CREATE POLICY "Admins can delete church images" ON public.church_images AS PERMISSIVE FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role = 'super_admin'::user_role) OR ((profiles.role = 'admin'::user_role) AND (profiles.church_id = church_images.church_id)) OR ((profiles.role = 'church_admin'::user_role) AND (profiles.assigned_church_id = church_images.church_id)) OR ((profiles.role = 'volunteer'::user_role) AND (profiles.assigned_church_id = church_images.church_id)))))));
CREATE POLICY "Admins can update church images" ON public.church_images AS PERMISSIVE FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role = 'super_admin'::user_role) OR ((profiles.role = 'admin'::user_role) AND (profiles.church_id = church_images.church_id)) OR ((profiles.role = 'church_admin'::user_role) AND (profiles.assigned_church_id = church_images.church_id)) OR ((profiles.role = 'volunteer'::user_role) AND (profiles.assigned_church_id = church_images.church_id)))))));
CREATE POLICY "Admins can upload church images" ON public.church_images AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((uploaded_by = auth.uid()) AND ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'super_admin'::user_role)))) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::user_role) AND (profiles.church_id = church_images.church_id)))) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'church_admin'::user_role) AND (profiles.assigned_church_id = church_images.church_id)))) OR (EXISTS ( SELECT 1
   FROM profiles
