CREATE POLICY "Admins can manage sacrament requirements" ON public.sacrament_requirements AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::user_role, 'super_admin'::user_role])) AND ((profiles.church_id = sacrament_requirements.church_id) OR (profiles.role = 'super_admin'::user_role))))));
CREATE POLICY "Anyone can view sacrament requirements" ON public.sacrament_requirements AS PERMISSIVE FOR SELECT TO public USING (true);
CREATE POLICY "Admins can manage service durations" ON public.service_durations AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::user_role, 'super_admin'::user_role])) AND ((profiles.church_id = service_durations.church_id) OR (profiles.role = 'super_admin'::user_role))))));
CREATE POLICY "Anyone can view service durations" ON public.service_durations AS PERMISSIVE FOR SELECT TO public USING (true);
CREATE POLICY "Admins can manage system announcements" ON public.system_announcements AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['admin'::user_role, 'super_admin'::user_role]))))));
CREATE POLICY "Public can read active system announcements" ON public.system_announcements AS PERMISSIVE FOR SELECT TO public USING (((is_active = true) AND ((expires_at IS NULL) OR (expires_at > now()))));
